begin;
create extension if not exists pgtap with schema extensions;
select plan(13);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values ('00000000-0000-0000-0000-000000003801','00000000-0000-0000-0000-000000000000','authenticated','authenticated','run-accounting@example.invalid','','{}','{}',now(),now());
insert into public.resource_registry(id,display_name,lifecycle_state,editorial_status) values ('00000000-0000-0000-0000-000000003811','Run service one','active','approved'),('00000000-0000-0000-0000-000000003812','Run service two','active','approved'),('00000000-0000-0000-0000-000000003813','Run service three','active','approved');
insert into public.resource_source_aliases(resource_id,source_type,source_native_id) values ('00000000-0000-0000-0000-000000003811','curated_bundle','curated:run-one'),('00000000-0000-0000-0000-000000003812','curated_bundle','curated:run-two'),('00000000-0000-0000-0000-000000003813','curated_bundle','curated:run-three');
insert into public.trusted_master_resource_records(id,resource_id,source_type,source_native_id,source_class,source_version,source_record_hash,original_address,normalized_address,municipality,physical_address) values ('00000000-0000-0000-0000-000000003821','00000000-0000-0000-0000-000000003811','curated_bundle','curated:run-one','trusted_curated_master_v1','test',repeat('1',64),'101 Main St','101 Main St, Surrey, BC','Surrey',true),('00000000-0000-0000-0000-000000003822','00000000-0000-0000-0000-000000003812','curated_bundle','curated:run-two','trusted_curated_master_v1','test',repeat('2',64),'102 Main St','102 Main St, Surrey, BC','Surrey',true),('00000000-0000-0000-0000-000000003823','00000000-0000-0000-0000-000000003813','curated_bundle','curated:run-three','trusted_curated_master_v1','test',repeat('3',64),'103 Main St','103 Main St, Surrey, BC','Surrey',true);
select ok(not has_function_privilege('anon','public.create_occupancy_claim_from_trusted_master_run(uuid,uuid,uuid,uuid)','execute'),'anonymous denied');
select is((public.begin_trusted_master_occupancy_bootstrap_run('00000000-0000-0000-0000-000000003831',2,'00000000-0000-0000-0000-000000003801')).authorized_max_successes,2,'run persists authorized cap');
select is(public.create_occupancy_claim_from_trusted_master_run('00000000-0000-0000-0000-000000003831','00000000-0000-0000-0000-000000003811','00000000-0000-0000-0000-000000003821','00000000-0000-0000-0000-000000003801')->>'outcome','created','first write succeeds');
select is(public.create_occupancy_claim_from_trusted_master_run('00000000-0000-0000-0000-000000003831','00000000-0000-0000-0000-000000003811','00000000-0000-0000-0000-000000003821','00000000-0000-0000-0000-000000003801')->>'outcome','idempotent','retry does not consume a slot');
select is((select successful_count from public.trusted_master_bootstrap_runs where id='00000000-0000-0000-0000-000000003831'),1,'retry leaves successful count unchanged');
select is(public.create_occupancy_claim_from_trusted_master_run('00000000-0000-0000-0000-000000003831','00000000-0000-0000-0000-000000003812','00000000-0000-0000-0000-000000003822','00000000-0000-0000-0000-000000003801')->>'outcome','created','second write reaches cap');
select is((select successful_count from public.trusted_master_bootstrap_runs where id='00000000-0000-0000-0000-000000003831'),2,'cap is persisted across resume');
select is((public.begin_trusted_master_occupancy_bootstrap_run('00000000-0000-0000-0000-000000003831',2,'00000000-0000-0000-0000-000000003801')).successful_count,2,'same run resumes rather than resetting');
select is(public.create_occupancy_claim_from_trusted_master_run('00000000-0000-0000-0000-000000003831','00000000-0000-0000-0000-000000003813','00000000-0000-0000-0000-000000003823','00000000-0000-0000-0000-000000003801')->>'outcome','refused','next write is refused at exact cap');
select throws_ok($$select public.begin_trusted_master_occupancy_bootstrap_run('00000000-0000-0000-0000-000000003831',3,'00000000-0000-0000-0000-000000003801')$$,null,'run binding does not match existing authorization','wrong run binding rejected');
select is((public.complete_trusted_master_occupancy_bootstrap_run('00000000-0000-0000-0000-000000003831','00000000-0000-0000-0000-000000003801')).status,'completed','run can be closed explicitly');
select throws_ok($$select public.begin_trusted_master_occupancy_bootstrap_run('00000000-0000-0000-0000-000000003831',2,'00000000-0000-0000-0000-000000003801')$$,null,'completed or stopped run cannot be restarted','completed run cannot silently restart');
select is((select count(*)::integer from public.resource_locations),0,'run accounting never creates locations');
select * from finish(); rollback;
